_COMPILED: dict[str, list[tuple[Element, re.Pattern]]] = {sec: [(el, re.compile('|'.join((f'(?:{c})' for c in el.cues)), re.IGNORECASE)) for el in els] for sec, els in ELEMENTS.items()}

def covered_sections() -> list[str]:
    return sorted(ELEMENTS)

def check_elements(ipc_section: str, narrative: str, utterance_id: str | None=None) -> list[ElementCheck]:
    spec = _COMPILED.get(ipc_section.strip().upper())
    if not spec:
        return []
    out: list[ElementCheck] = []
    for el, pattern in spec:
        hits = list(pattern.finditer(narrative))
        if hits:
            quotes = []
            prov = []
            seen: set[str] = set()
            for m in hits[:3]:
                q = m.group(0)
                if q.lower() in seen:
                    continue
                seen.add(q.lower())
                quotes.append(q)
                prov.append(Provenance(utterance_id=utterance_id, transcript_char_start=m.start(), transcript_char_end=m.end()))
            out.append(ElementCheck(element=el.name, satisfied='yes', justification='narrative says: ' + '; '.join((f"'{q}'" for q in quotes)), supporting_provenance=prov))
        else:
            out.append(ElementCheck(element=el.name, satisfied='unclear', justification='not stated in the narrative' + (f' -- establish: {el.note}' if el.note else '')))
    return out

@dataclass(frozen=True, slots=True)
class CueHit:
    ipc_section: str
    evidenced: int
    total: int
    cues: tuple[str, ...]

    @property
    def fraction(self) -> float:
        return self.evidenced / self.total if self.total else 0.0

def scan_all(narrative: str, min_fraction: float=1.0) -> list[CueHit]:
    hits: list[CueHit] = []
    for sec, spec in _COMPILED.items():
        matched: list[str] = []
        n_yes = 0
        for _el, pattern in spec:
            m = pattern.search(narrative)
            if m:
                n_yes += 1
                matched.append(m.group(0))
        if spec and n_yes / len(spec) >= min_fraction:
            hits.append(CueHit(sec, n_yes, len(spec), tuple(dict.fromkeys(matched))))
    hits.sort(key=lambda h: (-h.fraction, -h.total, h.ipc_section))
    return hits

def summarise(checks: list[ElementCheck]) -> str:
    if not checks:
        return 'elements not analysed'
    yes = sum((1 for c in checks if c.satisfied == 'yes'))
    return f'{yes}/{len(checks)} elements evidenced'
